changeSet.sql:
ALTER TABLE work_order
    ADD CONSTRAINT ck_work_order_dates
    CHECK (closed_at IS NULL OR closed_at >= opened_at);

ALTER TABLE drone_asset
    ADD CONSTRAINT ck_drone_asset_max_wind
    CHECK (maximum_wind_ms IS NULL OR maximum_wind_ms >= 0);

ALTER TABLE maintenance_intervention
    ADD CONSTRAINT ck_intervention_cost
    CHECK (work_cost IS NULL OR work_cost >= 0);
